import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.ost63GJL.js";const c=JSON.parse('{"title":"中国注册会计师审计准则第1101号（2022年修订）","description":"","frontmatter":{"title":"中国注册会计师审计准则第1101号（2022年修订）"},"headers":[],"relativePath":"auditing/csa/1101.md","filePath":"auditing/csa/1101.md","lastUpdated":1789486139000}'),s={name:"auditing/csa/1101.md"};function p(e,r,g,i,l,h){return a(),o("div",null,[...r[0]||(r[0]=[n('<h1 id="中国注册会计师审计准则第1101号——注册会计师的总体目标和审计工作的基本要求-2022年12月22日修订" tabindex="-1">中国注册会计师审计准则第1101号——注册会计师的总体目标和审计工作的基本要求（2022年12月22日修订） <a class="header-anchor" href="#中国注册会计师审计准则第1101号——注册会计师的总体目标和审计工作的基本要求-2022年12月22日修订" aria-label="Permalink to &quot;中国注册会计师审计准则第1101号——注册会计师的总体目标和审计工作的基本要求（2022年12月22日修订）&quot;">​</a></h1><h2 id="发文信息" tabindex="-1">发文信息 <a class="header-anchor" href="#发文信息" aria-label="Permalink to &quot;发文信息&quot;">​</a></h2><ul><li><strong>发文机关</strong>：财政部</li><li><strong>发布日期</strong>：2022-12-22</li><li><strong>生效日期</strong>：2023-07-01</li><li><strong>时效性</strong>：现行有效</li><li><strong>文号</strong>：财会〔2022〕36号</li><li><strong>原文链接</strong>：<a href="https://www.mof.gov.cn/" target="_blank" rel="noreferrer">财政部</a> ｜ <a href="https://www.cicpa.org.cn/" target="_blank" rel="noreferrer">中注协</a></li></ul><h2 id="第一章-总则" tabindex="-1">第一章 总则 <a class="header-anchor" href="#第一章-总则" aria-label="Permalink to &quot;第一章 总则&quot;">​</a></h2><p><strong>第一条</strong>　为了规范注册会计师按照中国注册会计师审计准则（简称审计准则）执行财务报表审计工作，确立注册会计师的总体目标，明确注册会计师为实现总体目标而需要执行审计工作的性质和范围，以及在执行财务报表审计业务时承担的责任，制定本准则。</p><p><strong>第二条</strong>　审计准则适用于注册会计师执行财务报表审计业务。</p><p>当执行其他历史财务信息审计业务时，注册会计师可以根据具体情况遵守适用的相关审计准则，以满足此类业务的要求。</p><h2 id="第二章-定义" tabindex="-1">第二章 定义 <a class="header-anchor" href="#第二章-定义" aria-label="Permalink to &quot;第二章 定义&quot;">​</a></h2><p><strong>第三条</strong>　注册会计师，是指取得注册会计师证书并在会计师事务所执业的人员，通常是指项目合伙人或项目组其他成员，有时也指其所在的会计师事务所。</p><p>当审计准则明确指出应由项目合伙人遵守的规定或承担的责任时，使用&quot;项目合伙人&quot;而非&quot;注册会计师&quot;的称谓。</p><p><strong>第四条</strong>　本准则所称财务报表，是指依据某一财务报告编制基础对被审计单位历史财务信息作出的结构性表述，旨在反映某一时点的经济资源或义务，或者某一时期经济资源或义务的变化。</p><p><strong>第五条</strong>　历史财务信息，是指以财务术语表述的某一特定实体的信息，这些信息主要来自特定实体的会计系统，反映了过去一段时间内发生的经济事项，或者过去某一时点的经济状况或情况。</p><p><strong>第六条</strong>　适用的财务报告编制基础，是指法律法规要求采用的财务报告编制基础；或者管理层和治理层（如适用）在编制财务报表时，就被审计单位性质和财务报表目标而言，采用的可接受的财务报告编制基础。</p><p>财务报告编制基础分为通用目的编制基础和特殊目的编制基础。</p><p>通用目的编制基础，是指旨在满足广大财务报表使用者共同的财务信息需求的财务报告编制基础，主要是指会计准则和会计制度。</p><p>特殊目的编制基础，是指旨在满足财务报表特定使用者财务信息需求的财务报告编制基础，包括计税核算基础、监管机构的要求和合同约定等。</p><p><strong>第七条</strong>　管理层，是指对被审计单位经营活动的执行负有经营管理责任的人员。在某些被审计单位，管理层包括部分或全部的治理层成员。</p><p><strong>第八条</strong>　治理层，是指对被审计单位战略方向以及管理层履行经营管理责任负有监督责任的人员或组织。治理层的责任包括监督财务报告过程。</p><p><strong>第九条</strong>　与管理层和治理层责任相关的执行审计工作的前提（以下简称执行审计工作的前提），是指管理层和治理层（如适用）认可并理解其应当承担下列责任：</p><p>（一）按照适用的财务报告编制基础编制财务报表，并使其实现公允反映（如适用）；</p><p>（二）设计、执行和维护必要的内部控制，以使财务报表不存在由于舞弊或错误导致的重大错报；</p><p>（三）向注册会计师提供必要的工作条件，包括允许注册会计师接触与编制财务报表相关的所有信息（如记录、文件和其他事项），向注册会计师提供审计所需的其他信息，允许注册会计师在获取审计证据时不受限制地接触其认为必要的内部人员和其他相关人员。</p><p><strong>第十条</strong>　错报，是指某一财务报表项目的金额、分类或列报，与按照适用的财务报告编制基础应当列示的金额、分类或列报之间存在的差异。错报可能是由于错误或舞弊导致的。</p><p><strong>第十一条</strong>　审计证据，是指注册会计师为了得出审计结论和形成审计意见而使用的信息。审计证据包括构成财务报表基础的会计记录所含有的信息和其他的信息。</p><p><strong>第十二条</strong>　合理保证，是指注册会计师在财务报表审计中提供的一种高度但非绝对的保证。</p><p><strong>第十三条</strong>　审计风险，是指当财务报表存在重大错报时，注册会计师发表不恰当审计意见的可能性。审计风险取决于重大错报风险和检查风险。</p><p><strong>第十四条</strong>　重大错报风险，是指财务报表在审计前存在重大错报的可能性。重大错报风险分为财务报表层次的重大错报风险和认定层次的重大错报风险。认定层次的重大错报风险由固有风险和控制风险两部分组成。</p><p><strong>第十五条</strong>　检查风险，是指如果存在某一错报，该错报单独或连同其他错报可能是重大的，注册会计师为将审计风险降低到可接受的低水平而实施程序后没有发现这种错报的风险。</p><p><strong>第十六条</strong>　职业判断，是指在审计准则、财务报告编制基础和职业道德要求的框架下，注册会计师综合运用相关知识、技能和经验，作出适合审计业务具体情况、有根据的行动决策。</p><p><strong>第十七条</strong>　职业怀疑，是指注册会计师执行审计业务的一种态度，包括采取质疑的思维方式，对可能表明由于错误或舞弊导致错报的迹象保持警觉，以及对审计证据进行审慎评价。</p><h2 id="第三章-财务报表审计" tabindex="-1">第三章 财务报表审计 <a class="header-anchor" href="#第三章-财务报表审计" aria-label="Permalink to &quot;第三章 财务报表审计&quot;">​</a></h2><p><strong>第十八条</strong>　审计的目的是提高财务报表预期使用者对财务报表的信赖程度。这一目的可以通过注册会计师对财务报表是否在所有重大方面按照适用的财务报告编制基础编制发表审计意见得以实现。</p><p><strong>第十九条</strong>　财务报表是由被审计单位管理层在治理层的监督下编制的。审计准则不对管理层或治理层设定责任，也不超越法律法规对管理层或治理层责任作出的规定。</p><p><strong>第二十条</strong>　注册会计师应当按照审计准则的规定，对财务报表整体是否不存在舞弊或错误导致的重大错报获取合理保证，以作为发表审计意见的基础。</p><p>合理保证是一种高水平保证。当注册会计师获取充分、适当的审计证据将审计风险降低到可接受的低水平时，就获取了合理保证。</p><p>由于审计存在固有限制，注册会计师据以得出结论和形成审计意见的大多数审计证据是说服性而非结论性的，因此，审计只能提供合理保证，不能提供绝对保证。</p><p><strong>第二十一条</strong>　在计划和执行审计工作，以及评价识别出的错报对审计的影响和未更正的错报（如有）对财务报表的影响时，注册会计师应当运用重要性概念。</p><p><strong>第二十二条</strong>　审计准则旨在规范和指导注册会计师对财务报表整体是否不存在重大错报获取合理保证，要求注册会计师在整个审计过程中运用职业判断和保持职业怀疑。</p><p><strong>第二十三条</strong>　注册会计师发表审计意见的形式取决于适用的财务报告编制基础以及相关法律法规的规定。</p><p><strong>第二十四条</strong>　按照审计准则和相关法律法规的规定，注册会计师还可能就审计中出现的事项，负有与管理层、治理层和其他财务报表使用者进行沟通和向其报告的责任。</p><h2 id="第四章-总体目标" tabindex="-1">第四章 总体目标 <a class="header-anchor" href="#第四章-总体目标" aria-label="Permalink to &quot;第四章 总体目标&quot;">​</a></h2><p><strong>第二十五条</strong>　在执行财务报表审计工作时，注册会计师的总体目标是：</p><p>（一）对财务报表整体是否不存在由于舞弊或错误导致的重大错报获取合理保证，使得注册会计师能够对财务报表是否在所有重大方面按照适用的财务报告编制基础编制发表审计意见；</p><p>（二）按照审计准则的规定，根据审计结果对财务报表出具审计报告，并与管理层和治理层沟通。</p><p><strong>第二十六条</strong>　在任何情况下，如果不能获取合理保证，并且在审计报告中发表保留意见也不足以实现向财务报表预期使用者报告的目的，注册会计师应当按照审计准则的规定出具无法表示意见的审计报告，或者在法律法规允许的情况下终止审计业务或解除业务约定。</p><h2 id="第五章-要求" tabindex="-1">第五章 要求 <a class="header-anchor" href="#第五章-要求" aria-label="Permalink to &quot;第五章 要求&quot;">​</a></h2><h3 id="第一节-与财务报表审计相关的职业道德要求" tabindex="-1">第一节 与财务报表审计相关的职业道德要求 <a class="header-anchor" href="#第一节-与财务报表审计相关的职业道德要求" aria-label="Permalink to &quot;第一节 与财务报表审计相关的职业道德要求&quot;">​</a></h3><p><strong>第二十七条</strong>　注册会计师应当遵守与财务报表审计相关的职业道德要求，包括遵守有关独立性的要求。</p><h3 id="第二节-职业怀疑" tabindex="-1">第二节 职业怀疑 <a class="header-anchor" href="#第二节-职业怀疑" aria-label="Permalink to &quot;第二节 职业怀疑&quot;">​</a></h3><p><strong>第二十八条</strong>　在计划和实施审计工作时，注册会计师应当保持职业怀疑，认识到可能存在导致财务报表发生重大错报的情形。</p><h3 id="第三节-职业判断" tabindex="-1">第三节 职业判断 <a class="header-anchor" href="#第三节-职业判断" aria-label="Permalink to &quot;第三节 职业判断&quot;">​</a></h3><p><strong>第二十九条</strong>　在计划和实施审计工作时，注册会计师应当运用职业判断。</p><h3 id="第四节-审计证据和审计风险" tabindex="-1">第四节 审计证据和审计风险 <a class="header-anchor" href="#第四节-审计证据和审计风险" aria-label="Permalink to &quot;第四节 审计证据和审计风险&quot;">​</a></h3><p><strong>第三十条</strong>　为了获取合理保证，注册会计师应当获取充分、适当的审计证据，以将审计风险降低到可接受的低水平，使其能够得出合理的结论，作为形成审计意见的基础。</p><h3 id="第五节-按照审计准则的规定执行审计工作" tabindex="-1">第五节 按照审计准则的规定执行审计工作 <a class="header-anchor" href="#第五节-按照审计准则的规定执行审计工作" aria-label="Permalink to &quot;第五节 按照审计准则的规定执行审计工作&quot;">​</a></h3><p><strong>第三十一条</strong>　注册会计师应当遵守与审计工作相关的所有审计准则。如果某项审计准则有效且所适用的情形存在，则该项审计准则与审计工作相关。</p><p><strong>第三十二条</strong>　注册会计师应当掌握审计准则及应用指南的全部内容，以理解每项审计准则的目标并恰当地遵守其要求。</p><p><strong>第三十三条</strong>　除非注册会计师已经遵守本准则以及与审计工作相关的其他所有审计准则，否则，注册会计师不得在审计报告中声称遵守了审计准则。</p><p><strong>第三十四条</strong>　为了实现注册会计师的总体目标，在计划和实施审计工作时，注册会计师应当运用相关审计准则规定的目标。</p><p><strong>第三十五条</strong>　除非存在下列情况之一，注册会计师应当遵守审计准则的所有要求：</p><p>（一）某项审计准则的全部内容与具体审计工作不相关；</p><p>（二）由于审计准则的某项要求存在适用条件，而该条件并不存在，导致该项要求不适用。</p><p><strong>第三十六条</strong>　在极其特殊的情况下，注册会计师可能认为有必要偏离某项审计准则的相关要求。在这种情况下，注册会计师应当实施替代审计程序以实现相关要求的目的。</p><p><strong>第三十七条</strong>　如果不能实现相关审计准则规定的目标，注册会计师应当评价这是否使其不能实现总体目标。如果不能实现总体目标，注册会计师应当按照审计准则的规定出具非无保留意见的审计报告，或者在法律法规允许的情况下解除业务约定。</p><p>不能实现相关审计准则规定的目标构成重大事项，注册会计师应当按照《中国注册会计师审计准则第1131号——审计工作底稿》的规定予以记录。</p><h2 id="第六章-附则" tabindex="-1">第六章 附则 <a class="header-anchor" href="#第六章-附则" aria-label="Permalink to &quot;第六章 附则&quot;">​</a></h2><p><strong>第三十八条</strong>　本准则自2023年7月1日起施行。</p>',67)])])}const u=t(s,[["render",p]]);export{c as __pageData,u as default};
